// PEGA SESSAO SALVA
const staticData = $getWorkflowStaticData('global');
const cookies = staticData.cookies || [];
const localStorage = staticData.localStorage || {};
const url = staticData.url || 'https://app.cotadorsimplificado.com.br';

if (cookies.length === 0) {
  return [{ json: { erro: true, mensagem: 'Nenhuma sessao salva! Execute o workflow 1 primeiro.' } }];
}

return [{ json: { cookies, localStorage, url } }];

const input = $input.first().json;

if (input.erro) {
  return [{ json: { code: null, erro: input.mensagem } }];
}

const cookies = JSON.stringify(input.cookies || []);
const localStorage = JSON.stringify(input.localStorage || {});
const lastUrl = input.url || 'https://app.cotadorsimplificado.com.br';

const code = `export default async function ({ page }) {
  const log = [];
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const cookies = ${cookies};
  const ls = ${localStorage};

  try {
    await page.setViewport({ width: 1280, height: 800 });
    log.push('Restaurando sessao...');
    await page.goto('${lastUrl}', { waitUntil: 'domcontentloaded', timeout: 30000 });
    if (cookies.length > 0) await page.setCookie(...cookies);
    await page.evaluate((ls) => {
      for (const [key, value] of Object.entries(ls)) {
        window.localStorage.setItem(key, value);
      }
    }, ls);
    await page.reload({ waitUntil: 'networkidle2' });
    await wait(2000);
    log.push('Sessao OK');

    log.push('Clicando PME...');
    await page.evaluate(() => {
      const pme = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29'));
      if (pme) pme.click();
    });
    await wait(3000);
    log.push('PME OK');

    log.push('Preenchendo nome...');
    await page.waitForSelector('#id-nomelead', { timeout: 10000 });
    const nomeInput = await page.$('#id-nomelead');
    if (nomeInput) {
      await nomeInput.click();
      await wait(500);
      await nomeInput.type('teste', { delay: 50 });
    }
    log.push('Nome OK');

    log.push('Avancando 1...');
    await page.evaluate(() => {
      const btn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Avan'));
      if (btn) btn.click();
    });
    await wait(3000);
    log.push('Avancar 1 OK');

    log.push('Preenchendo cidade...');
    await page.waitForSelector('#cidade_nome', { timeout: 10000 });
    const cidadeInput = await page.$('#cidade_nome');
    if (cidadeInput) {
      await cidadeInput.click();
      await wait(500);
      await cidadeInput.type('recife', { delay: 50 });
    }
    await wait(2000);
    await page.keyboard.press('ArrowDown');
    await wait(500);
    await page.keyboard.press('Enter');
    await wait(2000);
    log.push('Cidade OK');

    log.push('Selecionando empresa...');
    const selectEmpresa = '#index > div > div > div > div.bubble-element.Group.cnaTaBaK.bubble-r-container.flex.column > div.bubble-element.Group.coaJet.bubble-r-container.flex.column > div.bubble-element.Group.cnaTaAaH.bubble-r-container.flex.row > div.bubble-element.Group.cnaTaAaI.bubble-r-container.flex.column > div.bubble-element.Group.cnaTaAaN.bubble-r-container.flex.column > div.bubble-element.Group.coaIaGx.bubble-r-container.flex.row > select';
    await page.waitForSelector(selectEmpresa, { timeout: 5000 });
    await wait(500);
    await page.click(selectEmpresa);
    await wait(500);
    await page.evaluate(() => {
      const options = document.querySelectorAll('option');
      for (const opt of options) {
        if (opt.textContent.includes('MEI') && opt.textContent.includes('Empres')) {
          opt.selected = true;
          opt.parentElement.dispatchEvent(new Event('change', { bubbles: true }));
          break;
        }
      }
    });
    await wait(1000);
    log.push('Empresa OK');

    log.push('Avancando 2...');
    await page.evaluate(() => {
      const btn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Avan'));
      if (btn) btn.click();
    });
    await wait(3000);
    log.push('Avancar 2 OK');

    log.push('Preenchendo faixas...');
    const baseSelector = '#index > div > div > div > div.bubble-element.Group.cnaTaBaK.bubble-r-container.flex.column > div.bubble-element.Group.coaJet.bubble-r-container.flex.column > div.bubble-element.Group.cnaTaAaH.bubble-r-container.flex.row > div.bubble-element.CustomElement.cocyh.bubble-r-container.flex.column > div.bubble-element.RepeatingGroup.cocyn.bubble-rg > div.bubble-element.group-item.bubble-r-container.flex.column.entry-';
    let preenchidas = 0;
    for (let i = 1; i <= 10; i++) {
      try {
        const selector = baseSelector + i + ' > input';
        await page.waitForSelector(selector, { timeout: 2000 });
        await page.click(selector);
        await wait(200);
        await page.type(selector, '1');
        preenchidas++;
        await wait(200);
      } catch(e) {}
    }
    log.push('Faixas: ' + preenchidas);

    const screenshot = await page.screenshot({ encoding: 'base64' });
    return { success: true, log, url: page.url(), screenshot };
  } catch (error) {
    const screenshot = await page.screenshot({ encoding: 'base64' }).catch(() => null);
    return { success: false, error: error.message, log, screenshot };
  }
}`;

return [{ json: { code } }];

const input = $input.first().json;
const success = input.success;
const error = input.error || 'Nenhum';
const log = (input.log || []).join('
');
const url = input.url || '';

const texto = `*FORMULARIO HAPVIDA*

Status: ${success ? 'SUCESSO' : 'ERRO'}
Erro: ${error}

*Log:*
${log}

URL: ${url}`;

return [{ json: { number: '5583999471031', text: texto } }];
